{"l":6843,"g":7,"b":4,"cefr":"B1","role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad hedder 'fritidsjob' på engelsk i 'My brother has a ___ at the supermarket.'?","o":["spare job","free-time job","half job","part-time job"],"a":"part-time job","r":"Et fritidsjob hedder 'part-time job' på engelsk."},
{"l":6876,"g":7,"b":5,"cefr":"B1","role":"challenge","insight":"reframing","k":"h","variant":"authored","q":"Hvad betyder 'touch wood' i 'I haven't been ill all winter, touch wood.'?","o":["bank under bordet","hold fingrene væk","så er det sagt","det tror jeg ikke"],"a":"bank under bordet","r":"'Touch wood' siger man for at få held, ligesom bank under bordet."},
{"l":6910,"g":7,"b":5,"cefr":"B1","role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Everyone expected Ali to be nervous before his first speech. Instead, he smiled, made a joke and spoke without his notes.' Hvordan klarede Ali sin tale?","o":["Han glemte, hvad han skulle sige","Han var rolig og sikker","Han var meget nervøs","Han læste alt op fra papiret"],"a":"Han var rolig og sikker","r":"'Instead' viser, at det modsatte skete: han var rolig og talte frit."},
{"l":6911,"g":7,"b":5,"cefr":"B1","role":"challenge","insight":"reframing","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'genial / fantastisk' på engelsk i 'What a ___ idea!'?","o":["terrible","curious","brilliant","stupid"],"a":"brilliant","r":"'Brilliant' = fremragende."},
{"l":6938,"g":7,"b":5,"cefr":"B1","role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket ord passer: 'I've got ___ friends in Sweden, so I go there every summer.'","o":["a little","much","little","a few"],"a":"a few","r":"'Friends' kan tælles, så man bruger 'a few' = nogle få."},
{"l":6945,"g":7,"b":5,"cefr":"B1","role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad betyder 'pine' i 'A tall pine grew next to our cabin.'?","o":["fyrretræ","pine","birk","bøg"],"a":"fyrretræ","r":"'Pine' betyder fyrretræ. Falsk ven: dansk pine hedder 'pain' eller 'torment'."},
{"l":6949,"g":7,"b":5,"cefr":"B1","role":"challenge","insight":"reframing","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'holder med' på engelsk i 'Which team do you ___?'?","o":["watch","support","beat","coach"],"a":"support","r":"'Support a team' = holde med et hold."},
{"l":6962,"g":7,"b":5,"cefr":"B1","role":"challenge","insight":"reframing","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'udmattet' på engelsk i 'I'm ___ after the race'?","o":["excited","delighted","exhausted","surprised"],"a":"exhausted","r":"'Exhausted' = udmattet."},
{"l":6987,"g":7,"b":5,"cefr":"B1","role":"challenge","insight":"reframing","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'irriteret' på engelsk i 'He was ___ with his brother'?","o":["amused","pleased","impressed","annoyed"],"a":"annoyed","r":"'Annoyed' = irriteret."},
{"l":6999,"g":7,"b":5,"cefr":"B1","role":"challenge","insight":"reframing","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'genert' på engelsk i 'He is too ___ to speak in front of the class'?","o":["shy","old","sad","ill"],"a":"shy","r":"'Shy' betyder genert. Himlen hedder 'sky'."},
{"l":7000,"g":7,"b":5,"cefr":"B1","role":"challenge","insight":"reframing","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'i stedet' på engelsk i 'Let's walk ___'?","o":["together","instead","outside","anyway"],"a":"instead","r":"'Instead' = i stedet."},
{"l":7015,"g":7,"b":5,"cefr":"B2","role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvilket ord passer: 'He is ___ of heights, so he never goes on the big rides.'","o":["terrifying","terror","terrified","terrify"],"a":"terrified","r":"Han føler rædslen, så det er '-ed'-formen: 'terrified of'. 'Terrifying' beskriver noget, der skræmmer."},
{"l":7025,"g":7,"b":5,"cefr":"B2","role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'The sign said that the paint was still wet, but my little brother just had to touch it anyway.' Hvad siger teksten om lillebroren?","o":["Han kan ikke læse skiltet","Han er bange for maling","Han hjalp med at male","Han er nysgerrig og ulydig"],"a":"Han er nysgerrig og ulydig","r":"'Just had to' og 'anyway' viser, at han ikke kunne lade være, selv om skiltet advarede."},
{"l":7045,"g":7,"b":5,"cefr":"B2","role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Tim said he would be there at seven. At half past eight, his friends ordered pizza without him.' Hvad kan man slutte?","o":["Tim kom ikke til tiden","Tim bestilte pizzaen","Tim kom for tidligt","Tim var allerede gået"],"a":"Tim kom ikke til tiden","r":"Tim skulle komme klokken syv, men halvanden time senere bestilte vennerne uden ham."},
{"l":7060,"g":7,"b":5,"cefr":"B2","role":"challenge","insight":"reframing","k":"h","variant":"authored","q":"Hvad siger man på engelsk, når man vil sige, at noget ikke haster?","o":["There's no hurry up.","There's no rush.","It isn't any stress.","Take it quickly."],"a":"There's no rush.","r":"'There's no rush' betyder, at det ikke haster. 'Hurry up' betyder skynd dig."},
{"l":7075,"g":7,"b":5,"cefr":"B2","role":"challenge","insight":"reframing","k":"h","variant":"authored","q":"Hvad siger man på engelsk, når man vil berolige en ven, der har lavet en fejl?","o":["Don't worry, everyone is doing it.","It's your own fault, you know that.","Don't worry, it happens to everyone.","Never mind, I didn't see anything."],"a":"Don't worry, it happens to everyone.","r":"'It happens to everyone' betyder, at alle laver fejl. Det er trøstende."},
{"l":7095,"g":7,"b":5,"cefr":"B2","role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvilket ord betyder næsten det samme som 'entire' i 'the entire day'?","o":["empty","single","normal","whole"],"a":"whole","r":"'Entire' betyder hel, ligesom 'whole'."},
{"l":7120,"g":7,"b":5,"cefr":"B2","role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvilket ord betyder det modsatte af 'minor' i 'a minor injury'?","o":["major","slight","sudden","painful"],"a":"major","r":"'Minor' betyder lille eller mindre alvorlig, og 'major' betyder stor og alvorlig. 'Slight' betyder næsten det samme som 'minor'."},
{"l":7140,"g":7,"b":5,"cefr":"B2","role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad hedder 'rygte' på engelsk i 'There's a ___ that our teacher is leaving'?","o":["humour","rumour","message","review"],"a":"rumour","r":"Et rygte hedder 'rumour'. 'Humour' betyder humor og ligner kun ordet."},
{"l":7160,"g":8,"b":1,"cefr":"B2","role":"challenge","insight":"reframing","k":"h","variant":"authored","q":"Hvad betyder 'once in a while' i 'We go to the cinema once in a while'?","o":["kun én gang","hver eneste uge","en gang imellem","i et stykke tid"],"a":"en gang imellem","r":"'Once in a while' betyder en gang imellem, ikke særlig ofte."},
{"l":7180,"g":8,"b":1,"cefr":"B2","role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvilket ord passer: 'There was ___ traffic on the motorway this morning.'","o":["strong","big","hard","heavy"],"a":"heavy","r":"Tæt trafik hedder 'heavy traffic' på engelsk. 'Strong traffic' er en direkte oversættelse, der ikke bruges."},
{"l":7200,"g":8,"b":1,"cefr":"B2","role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'The library used to be silent. Since the café opened inside, it has become a place where people meet and chat.' Hvordan har biblioteket ændret sig?","o":["Det er blevet mere socialt","Det er blevet mere stille","Det har lukket caféen","Det har fået færre bøger"],"a":"Det er blevet mere socialt","r":"Før var der stille, nu mødes folk og snakker. 'Used to' viser, hvordan det var før."},
{"l":7225,"g":8,"b":1,"cefr":"B2","role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket ord passer: 'I had my eyes ___ yesterday.'","o":["test","tested","testing","to test"],"a":"tested","r":"'Have something done': efter objektet står den korte tillægsform, 'had my eyes tested'."},
{"l":7240,"g":8,"b":1,"cefr":"B2","role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvilket ord passer: 'She ___ up a new hobby during the summer holidays: pottery.'","o":["made","got","took","put"],"a":"took","r":"'Take up a hobby' betyder at begynde på en ny hobby."},
{"l":7270,"g":8,"b":1,"cefr":"B2","role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad hedder 'indkomst' på engelsk?","o":["outcome","intake","incoming","income"],"a":"income","r":"Indkomst hedder 'income'. 'Outcome' betyder resultat."},
{"l":7290,"g":8,"b":1,"cefr":"B2","role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket ord passer: 'He said he ___ call me the next day.'","o":["would","will","shall","is going"],"a":"would","r":"I indirekte tale bliver 'will' til 'would', når indledningen står i datid."},
{"l":7315,"g":8,"b":1,"cefr":"B2","role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket ord passer: 'We'll go for a picnic ___ it rains.'","o":["if","unless","so that","whether"],"a":"unless","r":"'Unless' betyder medmindre. Man tager på skovtur, medmindre det regner."},
{"l":7350,"g":8,"b":1,"cefr":"B2","role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'At first the twins refused to share a room. After a month, they complained when their parents suggested separating them again.' Hvad er der sket?","o":["De vil stadig ikke dele værelse","De er flyttet hjemmefra","De er blevet glade for at bo sammen","De har fået hvert sit værelse"],"a":"De er blevet glade for at bo sammen","r":"Nu klager de over at skulle skilles. De er altså kommet til at kunne lide at dele værelse."},
{"l":7370,"g":8,"b":1,"cefr":"B2","role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Ahmed had practised the speech for weeks, yet when he stood up, his hands were shaking.' Hvad viser teksten?","o":["At han slet ikke havde øvet sig på talen","At han frøs, fordi salen var kold","At han var syg den dag, han talte","At han var nervøs trods forberedelsen"],"a":"At han var nervøs trods forberedelsen","r":"'Yet' viser en modsætning: han havde øvet sig længe, men rystede alligevel af nervøsitet."},
{"l":7390,"g":8,"b":1,"cefr":"B2","role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvilket ord passer: 'The ___ of the town has grown rapidly since the new factory opened.'","o":["population","popularity","populated","popular"],"a":"population","r":"'Population' betyder befolkning. 'Popularity' betyder popularitet og passer ikke her."},
{"l":7410,"g":8,"b":1,"cefr":"B2","role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket ord passer: 'We ___ our kitchen painted last month.'","o":["made","had","did","took"],"a":"had","r":"'Have something done' betyder at få nogen til at gøre det for en. I datid: 'had our kitchen painted'."},
{"l":7440,"g":8,"b":2,"cefr":"B2","role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad hedder 'forsigtig' på engelsk?","o":["curious","conscious","cautious","anxious"],"a":"cautious","r":"Forsigtig hedder 'cautious'. 'Curious' betyder nysgerrig, og 'conscious' betyder bevidst."},
{"l":7465,"g":8,"b":2,"cefr":"B2","role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad betyder 'volunteers' i 'She volunteers at the animal shelter every Saturday'?","o":["arbejder for løn","bor i nærheden","køber dyrefoder","arbejder frivilligt"],"a":"arbejder frivilligt","r":"'Volunteer' som udsagnsord betyder at arbejde frivilligt, altså uden løn."},
{"l":7480,"g":8,"b":2,"cefr":"B2","role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket ord passer: '___ she had trained hard, she didn't win the race.'","o":["Although","Despite","However","In spite"],"a":"Although","r":"'Although' indleder en hel sætning med udsagnsled. 'Despite' kræver et navneord eller en -ing-form."},
{"l":7520,"g":8,"b":2,"cefr":"B2","role":"challenge","insight":"reframing","k":"h","variant":"authored","q":"Hvad betyder 'keep me posted' i 'Keep me posted about your trip'?","o":["skriv et postkort til mig","hold mig orienteret","pas godt på dig selv","ring til mig med det samme"],"a":"hold mig orienteret","r":"'Keep me posted' betyder, at man gerne vil høre nyt løbende. Det har intet med post at gøre."}
]$$::jsonb) AS e
JOIN (VALUES
  ('o', 'ordforråd', 'recall', 'factual', 'surface_association'),
  ('h', 'hverdagsudtryk', 'comprehension', 'conceptual', 'surface_association'),
  ('g', 'grammatik', 'application', 'applied', 'overgeneralization'),
  ('l', 'læseforståelse', 'analysis', 'inferential', 'surface_association')
) AS m(k, concept, skill, dtype, mis) ON m.k = e->>'k';
